            <Text
                eslint-disable-next-line
                no-param-reassign
                // eslint-disable-next-line no-param-reassign
                ref={(el) => (childRefs.current[index] = el)}
                style={[...textStyles, styles.pre]}
            >
                {displayName}
            </Text>
        </UserDetailsTooltip>
    );
}

function DisplayNames(props) {
    if (!props.tooltipEnabled) {
